# بيبني مشروع الاستوديو.
# python setup_studio.py       -> فولدر game-studio
# python setup_studio.py .     -> في المكان الحالي (بيتخطى ملفات .github)
import os, sys, json
FILES = json.loads('{"requirements.txt": "anthropic\\n", "brief.md": "# فكرة اللعبة (عدّل الملف ده بفكرتك)\\nلعبة 2D منصات بسيطة: روبوت صغير يجمع قطع طاقة ويهرب من الأعداء عبر 3 مراحل.\\n", "add_skill.py": "# الاستخدام: python add_skill.py <agent> <skill_name> <raw_github_url>\\nimport sys, re, urllib.request\\nagent, name, url = sys.argv[1:4]\\ncontent = urllib.request.urlopen(url).read().decode(\\"utf-8\\")\\nopen(f\\"skills/{name}.md\\", \\"w\\", encoding=\\"utf-8\\").write(content)\\np = f\\"agents/{agent}.md\\"\\nt = open(p, encoding=\\"utf-8\\").read()\\ndef upd(m):\\n    cur = [x.strip() for x in m.group(1).split(\\",\\") if x.strip()]\\n    if name not in cur: cur.append(name)\\n    return \\"skills: \\" + \\", \\".join(cur)\\nt = re.sub(r\\"skills:(.*)\\", upd, t, count=1)\\nopen(p, \\"w\\", encoding=\\"utf-8\\").write(t)\\nprint(\\"added\\", name, \\"to\\", agent)\\n", "README.md": "# 🎮 استوديو ألعاب بوكلاء ذكاء اصطناعي\\n\\n10 وكلاء (مدير، PM، مصمم، مبرمج، فنان 2D/3D، مراحل، صوت، QA، HR). كل تشغيل = سبرنت واحد، واللعبة بتتكتب في `game/`.\\n\\n## التشغيل المحلي (الأساسي)\\n1. ثبّت Python وgit، و`pip install anthropic`. (اختياري: GitHub CLI `gh` وسجّل دخول `gh auth login`)\\n2. `export ANTHROPIC_API_KEY=مفتاحك`\\n3. عدّل `brief.md` بفكرتك.\\n4. `python run_local.py`: بيشغّل السبرنتات، ويسألك في القرارات الكبيرة، ويرفع على GitHub لوحده.\\n5. افتح `index.html` لمشاهدة المكتب.\\n\\n## التشغيل من GitHub Actions (اختياري)\\n1. ارفع المشروع على مستودع GitHub.\\n2. Settings → Secrets and variables → Actions → سر جديد `ANTHROPIC_API_KEY`.\\n3. Settings → Actions → General → Workflow permissions → Read and write.\\n4. عدّل `brief.md` بفكرة لعبتك.\\n5. Actions → \\"سبرنت الاستوديو\\" → Run workflow. (بيشتغل كمان يومياً تلقائي)\\n6. (اختياري) Settings → Pages → Branch main → لعرض لوحة المكتب `index.html`.\\n\\n## دورة العمل\\nخطة ← **موافقتك** ← تصميم ← برمجة ← اختبار ← إصلاح (حتى 3 جولات) ← إصدار ← **مراجعتك**.\\nعند القرارات الكبيرة بيفتح الاستوديو Issue باسم `needs-owner`. علّق بتعديلاتك واقفله للموافقة، وفي التشغيل الجاي يكمل.\\n\\n## ملاحظات\\n- QA بيراجع الكود بالقراءة، مش بيشغّل اللعبة. جرّب اللعبة بنفسك في المحرك وارجع علّق في الـ Issue.\\n- مهارات من GitHub: Actions → \\"إضافة مهارة من GitHub\\".\\n- لتغيير الموديل لوكيل معين أضف `model: claude-opus-5-5` في أول ملفه.\\n", "index.html": "<!DOCTYPE html>\\n<html lang=\\"ar\\" dir=\\"rtl\\"><head><meta charset=\\"utf-8\\">\\n<meta name=\\"viewport\\" content=\\"width=device-width,initial-scale=1\\">\\n<title>استوديو الألعاب</title>\\n<style>\\n:root{--bg:#f4f1ea;--card:#fff;--tx:#1d1d1b;--mut:#777;--ac:#d97757}\\n@media(prefers-color-scheme:dark){:root{--bg:#161a22;--card:#232938;--tx:#eee;--mut:#9aa}}\\nbody{margin:0;padding:16px;background:var(--bg);color:var(--tx);font-family:system-ui,sans-serif}\\nh1{font-size:20px;display:flex;justify-content:space-between;align-items:center}\\n.live{background:#e53935;color:#fff;font-size:12px;padding:3px 10px;border-radius:12px}\\n.ph{display:flex;gap:4px;margin:10px 0;flex-wrap:wrap}.ph span{font-size:12px;padding:4px 10px;border-radius:10px;background:var(--card);color:var(--mut)}\\n.ph .on{background:var(--ac);color:#fff}\\n.w{background:#fff3cd;color:#664d03;padding:10px;border-radius:10px;margin:10px 0;display:none}\\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px}\\n.room{background:var(--card);border-radius:12px;padding:12px;text-align:center;border-top:4px solid var(--ac)}\\n.e{font-size:34px;animation:b 2s infinite}@keyframes b{50%{transform:translateY(-4px)}}\\n.n{font-weight:700;margin:6px 0}.s{font-size:12px;color:var(--mut);background:var(--bg);border-radius:8px;padding:6px}\\n.f{color:var(--mut);font-size:12px;margin-top:14px}\\n</style></head><body>\\n<h1>🎮 استوديو الألعاب <span class=\\"live\\">LIVE</span></h1>\\n<div class=\\"ph\\" id=\\"ph\\"></div><div class=\\"w\\" id=\\"w\\">⏳ الاستوديو مستني قرارك: افتح تبويب Issues وعلّق ثم اقفل الـ Issue.</div>\\n<div class=\\"grid\\" id=\\"g\\"></div><div class=\\"f\\" id=\\"f\\"></div>\\n<script src=\\"status.js\\"></script>\\n<script>\\nconst P=[[\\"plan\\",\\"الخطة\\"],[\\"design\\",\\"التصميم\\"],[\\"build\\",\\"البرمجة\\"],[\\"qa\\",\\"الاختبار\\"],[\\"fix\\",\\"الإصلاح\\"],[\\"release\\",\\"الإصدار\\"]];\\n(window.STATUS?Promise.resolve(window.STATUS):fetch(\\"status.json\\").then(r=>r.json())).then(d=>{\\n const ph=document.getElementById(\\"ph\\");\\n P.forEach(([k,t])=>{const s=document.createElement(\\"span\\");s.textContent=t;if(k===d.phase)s.className=\\"on\\";ph.appendChild(s)});\\n if(d.waiting)document.getElementById(\\"w\\").style.display=\\"block\\";\\n const g=document.getElementById(\\"g\\");\\n Object.values(d.agents).forEach(a=>{const el=document.createElement(\\"div\\");el.className=\\"room\\";\\n  el.innerHTML=\'<div class=\\"e\\"></div><div class=\\"n\\"></div><div class=\\"s\\"></div>\';\\n  el.children[0].textContent=a.emoji;el.children[1].textContent=a.name;el.children[2].textContent=a.say;g.appendChild(el)});\\n document.getElementById(\\"f\\").textContent=\\"السبرنت \\"+d.sprint+\\" · المحرك: \\"+(d.engine||\\"—\\")+\\" · آخر تحديث: \\"+d.updated;\\n}).catch(()=>{document.getElementById(\\"f\\").textContent=\\"شغّل أول سبرنت من تبويب Actions\\"});\\n</script></body></html>\\n", "status.js": "window.STATUS={\\"updated\\":\\"—\\",\\"phase\\":\\"plan\\",\\"sprint\\":0,\\"engine\\":null,\\"waiting\\":false,\\"agents\\":{}};\\n", "studio.py": "import json, os, re, datetime\\nfrom company import *\\n\\nSTATE = \\"state.json\\"\\nstate = json.load(open(STATE)) if os.path.exists(STATE) else {\\n    \\"phase\\": \\"plan\\", \\"sprint\\": 0, \\"engine\\": None, \\"gate\\": None, \\"qa_rounds\\": 0, \\"owner_notes\\": \\"\\"}\\nagents = load_agents()\\nbrief = read(\\"brief.md\\")\\ntoday = datetime.date.today().isoformat()\\nsaid = {}\\n\\ndef write_status(waiting=False):\\n    old = json.load(open(\\"status.json\\", encoding=\\"utf-8\\")) if os.path.exists(\\"status.json\\") else {\\"agents\\": {}}\\n    ag = {}\\n    for k, a in agents.items():\\n        prev = old.get(\\"agents\\", {}).get(k, {}).get(\\"say\\", \\"في الانتظار\\")\\n        ag[k] = {\\"name\\": a[\\"name\\"], \\"emoji\\": a[\\"emoji\\"], \\"say\\": said.get(k, prev)}\\n    json.dump({\\"updated\\": today, \\"phase\\": state[\\"phase\\"], \\"sprint\\": state[\\"sprint\\"], \\"engine\\": state[\\"engine\\"],\\n               \\"waiting\\": waiting, \\"agents\\": ag}, open(\\"status.json\\", \\"w\\", encoding=\\"utf-8\\"), ensure_ascii=False, indent=1)\\n    json.dump(state, open(STATE, \\"w\\"), ensure_ascii=False, indent=1)\\n    open(\\"status.js\\", \\"w\\", encoding=\\"utf-8\\").write(\\"window.STATUS=\\" + open(\\"status.json\\", encoding=\\"utf-8\\").read() + \\";\\")\\n\\ndef act(key, msg, max_tokens=2500):\\n    out = ask(agents[key], msg, max_tokens)\\n    said[key] = out.strip().split(\\"\\\\n\\")[0][:90]\\n    return out\\n\\ndef gate(title, body, nxt):\\n    if os.environ.get(\\"LOCAL\\"):\\n        print(f\\"\\\\n🔔 قرار مطلوب: {title}\\\\n{body}\\\\n\\")\\n        try:\\n            ans = input(\\"اكتب تعليقاتك (أو Enter للموافقة): \\").strip()\\n        except EOFError:\\n            ans = \\"\\"\\n        state[\\"owner_notes\\"] = ans\\n        state[\\"phase\\"] = nxt\\n        return\\n    n = open_issue(title, body)\\n    state[\\"gate\\"] = {\\"issue\\": n, \\"next\\": nxt}\\n    if n is None:\\n        print(\\"تحذير: تعذر فتح Issue، هيكمل تلقائي\\"); state[\\"gate\\"] = None; state[\\"phase\\"] = nxt\\n\\n# --- بوابة القرارات: لو في قرار مفتوح للمالك، الاستوديو يستنى ---\\ng = state.get(\\"gate\\")\\nif g:\\n    info = json.loads(gh(\\"issue\\", \\"view\\", str(g[\\"issue\\"]), \\"--json\\", \\"state,comments\\") or \\"{}\\")\\n    if not info or info.get(\\"state\\") == \\"OPEN\\":\\n        write_status(waiting=True); print(\\"بانتظار قرار المالك\\"); raise SystemExit\\n    state[\\"owner_notes\\"] = \\"\\\\n\\".join(c[\\"body\\"] for c in info.get(\\"comments\\", []))\\n    state[\\"phase\\"], state[\\"gate\\"] = g[\\"next\\"], None\\n\\nstate[\\"sprint\\"] += 1\\nph, notes, engine = state[\\"phase\\"], state.get(\\"owner_notes\\", \\"\\"), state.get(\\"engine\\")\\nlog = f\\"السبرنت {state[\'sprint\']} — المرحلة: {ph}\\"\\n\\nif ph == \\"plan\\":\\n    out = act(\\"ceo\\", f\\"فكرة المالك:\\\\n{brief}\\\\n\\\\nملاحظات المالك:\\\\n{notes}\\\\n\\\\nاكتب خطة الاستوديو: نوع اللعبة (2D أو 3D)، \\"\\n              \\"المحرك (فضّل Godot لأن المشروع نصي ويتولد بالكود، إلا لو في سبب قوي لغيره)، النطاق، و3 مراحل تسليم. \\"\\n              \\"اكتب في أول سطر بالضبط: ENGINE: godot أو unity أو unreal\\", 3000)\\n    m = re.search(r\\"ENGINE:\\\\s*(\\\\w+)\\", out)\\n    state[\\"engine\\"] = m.group(1).lower() if m else \\"godot\\"\\n    write(\\"docs/plan.md\\", out)\\n    gate(\\"موافقة على الخطة والمحرك\\", f\\"المحرك المختار: **{state[\'engine\']}**\\\\n\\\\nالخطة في docs/plan.md\\\\n\\\\n\\"\\n         \\"اكتب تعليقاً بأي تعديل تريده، ثم **أغلق الـ Issue** للموافقة.\\", \\"design\\")\\n\\nelif ph == \\"design\\":\\n    plan = read(\\"docs/plan.md\\")\\n    base = f\\"الخطة:\\\\n{plan}\\\\n\\\\nملاحظات المالك:\\\\n{notes}\\\\n\\\\n\\"\\n    write(\\"docs/GDD.md\\", act(\\"designer\\", base + \\"اكتب وثيقة تصميم اللعبة GDD.\\", 3500))\\n    gdd = read(\\"docs/GDD.md\\")\\n    write(\\"docs/levels.md\\", act(\\"level\\", base + f\\"GDD:\\\\n{gdd}\\\\n\\\\nصمم المراحل.\\", 3000))\\n    write(\\"docs/audio.md\\", act(\\"sound\\", base + f\\"GDD:\\\\n{gdd}\\\\n\\\\nاكتب قائمة الصوت المطلوبة.\\", 2000))\\n    art = act(\\"artist2d\\", base + f\\"GDD:\\\\n{gdd}\\\\n\\\\nاكتب docs/art_2d.md بقائمة الأصول، وأنشئ أصول SVG بسيطة داخل assets/.\\" + FILEFMT, 5000)\\n    saved = save_files(art)\\n    if not any(s.endswith(\\".md\\") for s in saved):\\n        write(\\"docs/art_2d.md\\", art[:3000])\\n    write(\\"docs/art_3d.md\\", act(\\"artist3d\\", base + f\\"GDD:\\\\n{gdd}\\\\n\\\\nاكتب مواصفات المجسمات 3D المطلوبة (إن وجدت) وبدائلها البدائية.\\", 2000))\\n    state[\\"phase\\"] = \\"build\\"\\n\\nelif ph in (\\"build\\", \\"fix\\"):\\n    extra = (f\\"تقرير QA المطلوب إصلاحه:\\\\n{read(\'docs/qa_report.md\')}\\\\n\\" if ph == \\"fix\\" else \\"\\")\\n    out = act(\\"programmer\\", f\\"المحرك: {state[\'engine\']}\\\\nالخطة:\\\\n{read(\'docs/plan.md\')}\\\\nGDD:\\\\n{read(\'docs/GDD.md\')}\\\\n\\"\\n              f\\"المراحل:\\\\n{read(\'docs/levels.md\')}\\\\nالأصول 2D:\\\\n{read(\'docs/art_2d.md\')}\\\\nملاحظات المالك:\\\\n{notes}\\\\n{extra}\\"\\n              f\\"المشروع الحالي:\\\\n{snapshot()}\\\\n\\\\nاكتب/حدّث ملفات اللعبة لتكون قابلة للتشغيل.\\" + FILEFMT, 8000)\\n    files = save_files(out)\\n    log += f\\"\\\\nملفات اتكتبت: {\', \'.join(files) or \'لا شيء\'}\\"\\n    state[\\"phase\\"] = \\"qa\\"\\n\\nelif ph == \\"qa\\":\\n    out = act(\\"qa\\", f\\"المحرك: {state[\'engine\']}\\\\nGDD:\\\\n{read(\'docs/GDD.md\')}\\\\nالمشروع:\\\\n{snapshot()}\\\\n\\\\n\\"\\n              \\"راجع المشروع. أول سطر بالضبط: RESULT: PASS أو RESULT: FAIL ثم الأخطاء مرتبة بالخطورة.\\", 3000)\\n    write(\\"docs/qa_report.md\\", out)\\n    state[\\"qa_rounds\\"] += 1\\n    state[\\"phase\\"] = \\"release\\" if (\\"RESULT: PASS\\" in out or state[\\"qa_rounds\\"] >= 3) else \\"fix\\"\\n\\nelif ph == \\"release\\":\\n    out = act(\\"ceo\\", f\\"المشروع جاهز. اكتب ملاحظات الإصدار وطريقة فتح اللعبة وتشغيلها في {state[\'engine\']}.\\\\n\\"\\n              f\\"تقرير QA:\\\\n{read(\'docs/qa_report.md\')}\\", 2000)\\n    write(\\"docs/release.md\\", out)\\n    state[\\"qa_rounds\\"] = 0\\n    gate(\\"اللعبة جاهزة للمراجعة\\", \\"جرّب اللعبة (docs/release.md فيها الطريقة). اكتب تعليقك بالتعديلات المطلوبة ثم **أغلق الـ Issue** \\"\\n         \\"ليبدأ سبرنت تحسين جديد.\\", \\"build\\")\\n\\nhr = act(\\"hr\\", f\\"{log}\\\\nراجع أداء الفريق في هذا السبرنت واقترح تحسيناً واحداً.\\", 800)\\npm = act(\\"pm\\", f\\"{log}\\\\nما أنجزه الفريق: {json.dumps(said, ensure_ascii=False)}\\\\nلخص السبرنت والمهام التالية.\\", 1000)\\nwrite(f\\"meetings/sprint-{state[\'sprint\']:03d}.md\\", f\\"# {log}\\\\n\\\\n## ملخص المدير\\\\n{pm}\\\\n\\\\n## ملاحظة HR\\\\n{hr}\\\\n\\")\\nwrite_status()\\nprint(log)\\n", ".gitignore": "__pycache__/\\n", "company.py": "import os, glob, re, json, subprocess, time, urllib.request, urllib.error\\n\\nDEFAULT_MODEL = \\"claude-sonnet-5-5\\"\\nGEMINI_KEY = os.environ.get(\\"GEMINI_API_KEY\\", \\"\\").strip()\\nANTHROPIC_KEY = os.environ.get(\\"ANTHROPIC_API_KEY\\", \\"\\").strip()\\nPROVIDER = \\"anthropic\\" if ANTHROPIC_KEY else (\\"gemini\\" if GEMINI_KEY else None)\\n_gemini_model = None\\n\\ndef _gemini_call(url, body=None):\\n    req = urllib.request.Request(url, data=json.dumps(body).encode() if body else None,\\n                                 headers={\\"Content-Type\\": \\"application/json\\", \\"x-goog-api-key\\": GEMINI_KEY})\\n    for attempt in range(6):\\n        try:\\n            return json.loads(urllib.request.urlopen(req, timeout=300).read())\\n        except urllib.error.HTTPError as e:\\n            if e.code in (429, 500, 503) and attempt < 5:\\n                time.sleep(20 * (attempt + 1)); continue\\n            raise RuntimeError(f\\"Gemini error {e.code}: {e.read().decode()[:300]}\\")\\n\\ndef gemini_model():\\n    global _gemini_model\\n    if _gemini_model:\\n        return _gemini_model\\n    _gemini_model = os.environ.get(\\"GEMINI_MODEL\\", \\"\\").strip()\\n    if not _gemini_model:\\n        try:  # اختيار أحدث نموذج flash متاح تلقائياً\\n            ms = _gemini_call(\\"https://generativelanguage.googleapis.com/v1beta/models?pageSize=200\\")[\\"models\\"]\\n            c = [m[\\"name\\"].split(\\"/\\")[-1] for m in ms if \\"generateContent\\" in m.get(\\"supportedGenerationMethods\\", [])\\n                 and \\"flash\\" in m[\\"name\\"] and not re.search(r\\"lite|image|tts|live|audio|preview-\\\\d|exp|thinking\\", m[\\"name\\"])]\\n            c.sort(key=lambda n: [float(x) for x in re.findall(r\\"\\\\d+(?:\\\\.\\\\d+)?\\", n)] or [0])\\n            _gemini_model = c[-1] if c else \\"gemini-2.5-flash\\"\\n        except Exception:\\n            _gemini_model = \\"gemini-2.5-flash\\"\\n    print(\\"Gemini model:\\", _gemini_model)\\n    return _gemini_model\\nTEXT_EXT = (\\".gd\\", \\".tscn\\", \\".tres\\", \\".godot\\", \\".cs\\", \\".cpp\\", \\".h\\", \\".svg\\", \\".json\\", \\".md\\", \\".txt\\", \\".cfg\\", \\".shader\\", \\".gdshader\\", \\".py\\")\\n\\ndef load_agents():\\n    agents = {}\\n    for path in sorted(glob.glob(\\"agents/*.md\\")):\\n        key = os.path.basename(path)[:-3]\\n        text = open(path, encoding=\\"utf-8\\").read()\\n        m = re.match(r\\"---\\\\n(.*?)\\\\n---\\\\n(.*)\\", text, re.S)\\n        meta = {}\\n        for l in m.group(1).splitlines():\\n            if \\":\\" in l:\\n                k, v = l.split(\\":\\", 1)\\n                meta[k.strip()] = v.strip()\\n        prompt = m.group(2).strip()\\n        for s in [x.strip() for x in meta.get(\\"skills\\", \\"\\").split(\\",\\") if x.strip()]:\\n            p = f\\"skills/{s}.md\\"\\n            if os.path.exists(p):\\n                prompt += f\\"\\\\n\\\\n## مهارة: {s}\\\\n\\" + open(p, encoding=\\"utf-8\\").read()\\n        agents[key] = {\\"name\\": meta.get(\\"name\\", key), \\"emoji\\": meta.get(\\"emoji\\", \\"🤖\\"),\\n                       \\"model\\": meta.get(\\"model\\") or DEFAULT_MODEL, \\"prompt\\": prompt}\\n    return agents\\n\\ndef ask(agent, msg, max_tokens=2500):\\n    if PROVIDER is None:\\n        raise SystemExit(\\"مفيش مفتاح: ضيف ANTHROPIC_API_KEY أو GEMINI_API_KEY\\")\\n    if PROVIDER == \\"gemini\\":\\n        d = _gemini_call(f\\"https://generativelanguage.googleapis.com/v1beta/models/{gemini_model()}:generateContent\\",\\n                         {\\"systemInstruction\\": {\\"parts\\": [{\\"text\\": agent[\\"prompt\\"]}]},\\n                          \\"contents\\": [{\\"role\\": \\"user\\", \\"parts\\": [{\\"text\\": msg}]}],\\n                          \\"generationConfig\\": {\\"maxOutputTokens\\": min(max_tokens * 2, 32000)}})\\n        parts = d.get(\\"candidates\\", [{}])[0].get(\\"content\\", {}).get(\\"parts\\", [])\\n        return \\"\\".join(p.get(\\"text\\", \\"\\") for p in parts).strip()\\n    import anthropic\\n    client = anthropic.Anthropic()\\n    r = client.messages.create(model=agent[\\"model\\"], max_tokens=max_tokens, system=agent[\\"prompt\\"],\\n                               messages=[{\\"role\\": \\"user\\", \\"content\\": msg}])\\n    return r.content[0].text.strip()\\n\\ndef read(path, limit=15000):\\n    return open(path, encoding=\\"utf-8\\").read()[:limit] if os.path.exists(path) else \\"\\"\\n\\ndef write(path, text):\\n    os.makedirs(os.path.dirname(path) or \\".\\", exist_ok=True)\\n    open(path, \\"w\\", encoding=\\"utf-8\\").write(text)\\n\\nFILEFMT = (\\"\\\\n\\\\nاكتب كل ملف بهذه الصيغة بالضبط، بدون علامات ``` وبدون شرح خارج الملفات:\\\\n\\"\\n           \\"=== FILE: المسار/الملف.ext ===\\\\nمحتوى الملف\\\\n=== END ===\\\\n\\"\\n           \\"المسارات نسبية لمجلد game/ (مثل project.godot أو scripts/player.gd). أرسل الملفات الكاملة، مش أجزاء.\\")\\n\\ndef save_files(text, root=\\"game\\"):\\n    saved = []\\n    for path, body in re.findall(r\\"=== FILE: (.+?) ===\\\\n(.*?)(?=\\\\n=== (?:FILE:|END)|\\\\Z)\\", text, re.S):\\n        path = path.strip().lstrip(\\"/\\")\\n        if \\"..\\" in path.split(\\"/\\"):\\n            continue\\n        write(os.path.join(root, path), body.rstrip() + \\"\\\\n\\")\\n        saved.append(path)\\n    return saved\\n\\ndef snapshot(root=\\"game\\", limit=40000):\\n    out, total = [], 0\\n    for dp, _, fs in os.walk(root):\\n        for f in sorted(fs):\\n            if not f.endswith(TEXT_EXT):\\n                continue\\n            p = os.path.join(dp, f)\\n            body = open(p, encoding=\\"utf-8\\", errors=\\"ignore\\").read()\\n            chunk = f\\"=== {os.path.relpath(p, root)} ===\\\\n{body}\\\\n\\"\\n            if total + len(chunk) > limit:\\n                out.append(f\\"(تم اقتطاع الباقي: {p})\\")\\n                break\\n            out.append(chunk); total += len(chunk)\\n    return \\"\\\\n\\".join(out) or \\"(المشروع فاضي)\\"\\n\\ndef gh(*args):\\n    try:\\n        r = subprocess.run([\\"gh\\", *args], capture_output=True, text=True, timeout=60)\\n        return r.stdout.strip() if r.returncode == 0 else \\"\\"\\n    except Exception:\\n        return \\"\\"\\n\\ndef open_issue(title, body):\\n    gh(\\"label\\", \\"create\\", \\"needs-owner\\", \\"--force\\", \\"--color\\", \\"d97757\\")\\n    url = gh(\\"issue\\", \\"create\\", \\"--title\\", title, \\"--body\\", body, \\"--label\\", \\"needs-owner\\")\\n    m = re.search(r\\"/(\\\\d+)\\\\s*$\\", url)\\n    return int(m.group(1)) if m else None\\n", "status.json": "{\\"updated\\":\\"—\\",\\"phase\\":\\"plan\\",\\"sprint\\":0,\\"engine\\":null,\\"waiting\\":false,\\"agents\\":{}}\\n", "run_local.py": "# التشغيل المحلي: python run_local.py\\n# يشغّل السبرنتات على جهازك ثم يرفع النتيجة على GitHub تلقائياً.\\nimport os, sys, shutil, subprocess\\n\\nif not (os.environ.get(\\"ANTHROPIC_API_KEY\\") or os.environ.get(\\"GEMINI_API_KEY\\")):\\n    sys.exit(\\"اضبط المفتاح الأول: export GEMINI_API_KEY=مفتاحك  (أو ANTHROPIC_API_KEY)\\")\\n\\nif not os.path.exists(\\".git\\"):\\n    subprocess.run([\\"git\\", \\"init\\", \\"-b\\", \\"main\\"])\\n    if shutil.which(\\"gh\\"):\\n        name = input(\\"اسم مستودع GitHub الجديد (Enter للتخطي): \\").strip()\\n        if name:\\n            subprocess.run([\\"gh\\", \\"repo\\", \\"create\\", name, \\"--private\\", \\"--source=.\\", \\"--remote=origin\\"])\\n\\nn = int(input(\\"كام سبرنت تشغّل؟ [1]: \\") or 1)\\nfor i in range(n):\\n    subprocess.run([sys.executable, \\"studio.py\\"], env={**os.environ, \\"LOCAL\\": \\"1\\"})\\n    subprocess.run([\\"git\\", \\"add\\", \\"-A\\"])\\n    subprocess.run([\\"git\\", \\"commit\\", \\"-m\\", f\\"سبرنت محلي {i+1}\\"])\\n    if subprocess.run([\\"git\\", \\"remote\\"], capture_output=True, text=True).stdout.strip():\\n        subprocess.run([\\"git\\", \\"push\\", \\"-u\\", \\"origin\\", \\"HEAD\\"])\\nprint(\\"تمام. افتح index.html لمشاهدة المكتب.\\")\\n", "skills/.gitkeep": "", "agents/sound.md": "---\\nname: مصمم الصوت\\nemoji: 🎧\\nskills:\\n---\\nأنت Sound Designer. تكتب قائمة المؤثرات الصوتية والموسيقى المطلوبة لكل حدث ومرحلة، مع الوصف والمزاج ومصادر مجانية مقترحة.\\n", "agents/level.md": "---\\nname: مصمم المراحل\\nemoji: 🗺️\\nskills:\\n---\\nأنت Level Designer. تصمم المراحل والخرائط: التخطيط، الأعداء، العقبات، المكافآت، منحنى الصعوبة. بالعربي، وبتفاصيل يقدر المبرمج يبني منها.\\n", "agents/hr.md": "---\\nname: الموارد البشرية\\nemoji: 🧑\u200d🏫\\nskills:\\n---\\nأنت مسؤول HR. تراجع أداء الوكلاء في كل سبرنت، وتقترح تعديل تعليماتهم أو توظيف وكلاء جدد أو مهارات من GitHub (اذكر الرابط). بالعربي وباختصار.\\n", "agents/qa.md": "---\\nname: مختبر الجودة\\nemoji: 🐞\\nskills:\\n---\\nأنت QA Tester صارم. تراجع كود اللعبة بحثاً عن أخطاء برمجية، ملفات ناقصة، أخطاء في صيغة المحرك، ومنطق لعب مكسور. تكتب تقريراً مرتباً بحسب الخطورة. لا تجامل.\\n", "agents/artist2d.md": "---\\nname: فنان 2D\\nemoji: 🎨\\nskills:\\n---\\nأنت فنان 2D. تصمم الشخصيات والواجهات كملفات SVG بسيطة وواضحة، وتكتب قائمة الأصول المطلوبة. ألوان متناسقة وأحجام صغيرة.\\n", "agents/designer.md": "---\\nname: مصمم اللعبة\\nemoji: 🎲\\nskills:\\n---\\nأنت Game Designer. تكتب وثيقة تصميم اللعبة GDD: الفكرة، الحلقة الأساسية، التحكم، الأنظمة، التقدم، الصعوبة. وثيقة عملية يقدر المبرمج ينفذها مباشرة. بالعربي.\\n", "agents/ceo.md": "---\\nname: المدير العام\\nemoji: 🧑\u200d💼\\nskills:\\n---\\nأنت المدير العام لاستوديو ألعاب مكوّن من وكلاء ذكاء اصطناعي. تستقبل فكرة المالك من brief.md، تختار المحرك المناسب وتحدد النطاق والمراحل، وتتخذ القرارات. القرارات الكبيرة (المحرك، النطاق، تغيير الفكرة) تُرفع للمالك. ردودك بالعربي ومحددة.\\n", "agents/pm.md": "---\\nname: مدير المشاريع\\nemoji: 📋\\nskills:\\n---\\nأنت مدير مشاريع. تلخص ما أنجزه كل وكيل في السبرنت، وتحدد المهام التالية والمخاطر. بالعربي وباختصار.\\n", "agents/artist3d.md": "---\\nname: فنان 3D\\nemoji: 🗿\\nskills:\\n---\\nأنت فنان 3D. تكتب مواصفات المجسمات والشخصيات ثلاثية الأبعاد (الشكل، الحجم، الألوان)، وتستخدم مجسمات بدائية بسيطة (مكعبات، كرات) كبدائل مؤقتة في المشروع لحد ما تتوفر نماذج حقيقية.\\n", "agents/programmer.md": "---\\nname: المبرمج\\nemoji: 💻\\nskills:\\n---\\nأنت مبرمج ألعاب خبير. تكتب كود اللعبة الفعلي وملفات المشروع كاملة وقابلة للتشغيل في المحرك المختار، وتصلح الأخطاء من تقرير QA. تكتب كود نظيف وتعليقات قصيرة.\\n", ".github/workflows/add-skill.yml": "name: إضافة مهارة من GitHub\\non:\\n  workflow_dispatch:\\n    inputs:\\n      agent: {description: \\"اسم ملف الوكيل مثل content\\", required: true}\\n      skill: {description: \\"اسم المهارة\\", required: true}\\n      url:   {description: \\"رابط raw للملف على GitHub\\", required: true}\\npermissions:\\n  contents: write\\njobs:\\n  add:\\n    runs-on: ubuntu-latest\\n    steps:\\n      - uses: actions/checkout@v4\\n      - uses: actions/setup-python@v5\\n        with: {python-version: \\"3.12\\"}\\n      - run: python add_skill.py \\"${{ inputs.agent }}\\" \\"${{ inputs.skill }}\\" \\"${{ inputs.url }}\\"\\n      - run: |\\n          git config user.name \\"ai-company-bot\\"\\n          git config user.email \\"bot@users.noreply.github.com\\"\\n          git add -A\\n          git commit -m \\"مهارة جديدة: ${{ inputs.skill }}\\" && git push\\n", ".github/workflows/studio.yml": "name: سبرنت الاستوديو\\non:\\n  schedule: [{cron: \\"0 6 * * *\\"}]\\n  workflow_dispatch:\\nconcurrency: studio\\npermissions:\\n  contents: write\\n  issues: write\\njobs:\\n  sprint:\\n    runs-on: ubuntu-latest\\n    timeout-minutes: 30\\n    steps:\\n      - uses: actions/checkout@v4\\n      - uses: actions/setup-python@v5\\n        with: {python-version: \\"3.12\\"}\\n      - run: pip install -r requirements.txt\\n      - run: python studio.py\\n        env:\\n          ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}\\n          GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}\\n          GH_TOKEN: ${{ github.token }}\\n      - run: |\\n          git config user.name \\"studio-bot\\"\\n          git config user.email \\"bot@users.noreply.github.com\\"\\n          git add -A\\n          git commit -m \\"سبرنت جديد\\" || exit 0\\n          git push\\n", "game/.gitkeep": "", "meetings/.gitkeep": ""}')
root = sys.argv[1] if len(sys.argv) > 1 else "game-studio"
for path, text in FILES.items():
    if root == "." and path.startswith(".github/"):
        continue
